"""JSON Schema rendering shared by the exporter and the stream-schema hash."""

import hashlib
import json
from typing import Any

from pydantic import BaseModel

DIALECT = "https://json-schema.org/draft/2020-12/schema"


def render(model: type[BaseModel]) -> str:
    schema: dict[str, Any] = {
        **model.model_json_schema(),
        "$schema": DIALECT,
        "$comment": f"generated by make gen from {model.__module__}.{model.__name__} - do not edit",
    }
    return json.dumps(schema, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def schema_sha12(model: type[BaseModel]) -> str:
    return hashlib.sha256(render(model).encode("utf-8")).hexdigest()[:12]
